/* Demonstrates using syscall() to invoke getpid(2) and getppid(2) */
#include <stdio.h>
#include <unistd.h>
#include <sys/syscall.h>
#include <errno.h>

int main() {
    long pid_result;
    long ppid_result;

    // 1. Invoke getpid(2). Takes zero arguments.
    // SYS_getpid is the numerical constant for the getpid syscall.
    pid_result = syscall(SYS_getpid);

    if (pid_result == -1) {
        perror("syscall(SYS_getpid) failed");
        return 1;
    }

    printf("Process ID obtained via syscall(): %ld\n", pid_result);

    // 2. Invoke getppid(2). Also takes zero arguments.
    ppid_result = syscall(SYS_getppid);

    if (ppid_result == -1) {
        // Error handling via standard errno mechanism
        perror("syscall(SYS_getppid) failed");
        return 1;
    }
    printf("Parent Process ID obtained via syscall(): %ld\n", ppid_result);

    return 0;
}
